use std::collections::HashMap;

fn bump(map: &mut HashMap<String, i32>, key: &str) -> i32 {
    let current = map.get(key).copied().unwrap_or(0);
    let new_val = current + 1;
    map.insert(key.to_string(), new_val);
    new_val
}

fn double_bump(map: &mut HashMap<String, i32>, key: &str) -> i32 {
    let current = map.get(key).unwrap();
    map.insert(key.to_string(), current + 1);
    *current + 1
}

fn main() {
    let mut m = HashMap::new();
    m.insert(String::from("a"), 5);
    println!("{}", bump(&mut m, "a"));
    println!("{}", double_bump(&mut m, "a"));
}
